<script>
'use strict';
(() => {
const seed=JSON.parse(document.getElementById('mock-seed').textContent);
const clone=x=>JSON.parse(JSON.stringify(x));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tid=id=>document.querySelector(`[data-testid="${id}"]`);
const val=id=>tid(id)?.value??'';
const money=n=>`${Number(n).toLocaleString('th-TH',{maximumFractionDigits:2})} บาท`;
const cents=n=>Math.round(Number(n)*100);
const sum=items=>items.reduce((a,i)=>a+cents(i.total),0)/100;
const statuses=['รับออเดอร์','กำลังทำ','เสร็จแล้ว'];
let s,u,epoch=0;
function iso(t=s.now){return new Date(t+7*3600000).toISOString().slice(0,19)+'+07:00';}
function day(t=s.now){return iso(t).slice(0,10);}
function reset(){
 epoch++;
 s={menus:clone(seed.menus),ingredients:clone(seed.ingredients),mappings:clone(seed.ingredient_mappings),accounts:seed.staff.map(a=>({...a,pin:seed.demo_pin,failures:0,lockedUntil:0})),tables:clone(seed.tables),sessions:[],orders:[],items:[],payments:[],paymentEvents:[],statusEvents:[],now:Date.parse(seed.clock.initial),promptpay:seed.promptpay_enabled,nextOrder:1,nextSession:1,nextMenu:9,nextOption:1,nextItem:1,takeawayDay:dayFromSeed(),takeawaySequence:0};
 u={role:'customer',user:null,page:'',auth:'',loginUser:'demokitchen',mode:'dine-in',table:'01',session:null,takeawayCart:[],takeawayOpened:false,selectedMenu:null,selectedOptions:[],slot:null,orderMessage:'',frontTable:'01',ingredient:'rice',mappingMenu:'m01',mappingScope:'whole',mappingOption:'extra-egg',mappingIngredient:'rice',mappingMessage:'',adminId:'new',draft:null,adminMessage:'',accountMessage:'',frontMessage:''};
 history.replaceState(null,'',location.pathname+location.search);render();
}
function dayFromSeed(){return seed.clock.initial.slice(0,10);}
function can(area){return !!u.user&&(u.user.role==='manager'||u.user.role===area);}
function deny(){u.auth='ปฏิเสธ: บัญชีนี้ไม่มีสิทธิ์เข้าหน้านี้ (PIN/สิทธิ์จำลอง)';render();}
function session(){return s.sessions.find(x=>x.id===u.session);}
function currentCart(){return u.mode==='takeaway'?u.takeawayCart:(session()?.cart??[]);}
function sessionOrders(){return s.orders.filter(o=>u.mode==='takeaway'?o.channel==='takeaway':o.session_id===u.session&&session()?.state==='open');}
function latest(){return sessionOrders().at(-1);}
function payment(o){return s.payments.find(p=>p.order_id===o?.id);}
function orderItems(o){return s.items.filter(i=>i.order_id===o.id);}
function blocked(menuId,scope,optionId=null){return s.mappings.some(m=>m.menu_id===menuId&&m.scope===scope&&(scope==='whole'||m.option_id===optionId)&&!s.ingredients.find(i=>i.id===m.ingredient_id)?.available);}
function menuAvailable(m){return !!m&&m.available&&!blocked(m.id,'whole');}
function optionAvailable(m,o){return menuAvailable(m)&&!blocked(m.id,'option',o.id);}
function choices(rows,selected,key='id',label='name'){return rows.map(r=>`<option value="${esc(r[key])}" ${r[key]===selected?'selected':''}>${esc(r[label])}</option>`).join('');}
function button(testid,label,action,extra=''){return `<button ${testid?`data-testid="${testid}"`:''} data-action="${action}" ${extra}>${label}</button>`;}
function slots(){const start=Math.ceil((s.now+20*60000)/(15*60000))*15*60000;return Array.from({length:8},(_,i)=>{const t=start+i*15*60000;return {t,value:iso(t).slice(11,16)+'-'+iso(t+15*60000).slice(11,16),date:day(t)};});}
function ensureSlot(){const list=slots();if(!list.some(x=>x.t===u.slot))u.slot=list[0].t;return list;}
function openTable(table){let x=s.sessions.find(x=>x.table_id===table&&x.state==='open');if(!x){x={id:'S-'+String(s.nextSession++).padStart(4,'0'),table_id:table,state:'open',opened_at:iso(),closed_at:null,cart:[]};s.sessions.push(x);}return x;}
function openMenu(){if(u.mode==='dine-in'){const next=openTable(u.table);if(u.session!==next.id){u.selectedMenu=null;u.selectedOptions=[];u.orderMessage='';}u.session=next.id;}else{u.takeawayOpened=true;ensureSlot();}render();}
function render(){
 const focused=document.activeElement;const focusKey=focused?.getAttribute('data-testid');const focusAction=focused?.getAttribute('data-action');const focusId=focused?.getAttribute('data-id');
 tid('sim-clock').textContent=iso();tid('auth-message').textContent=u.auth;
 for(const role of ['customer','staff','manager'])tid('role-'+role).setAttribute('aria-pressed',String(u.role===role));
 document.getElementById('auth').innerHTML=u.role!=='customer'&&!u.user?loginHTML():'';
 let html='';if(u.role==='customer')html=customerHTML();else if(u.role==='manager'&&u.user?.role==='manager')html=managerHTML();else if(u.role==='staff')html=staffHTML();
 document.getElementById('screens').innerHTML=html;
 if(focusKey){const el=tid(focusKey);if(el&&!el.disabled)el.focus({preventScroll:true});}
 else if(focusAction){const el=[...document.querySelectorAll('[data-action]')].find(e=>e.dataset.action===focusAction&&e.dataset.id===focusId);if(el&&!el.disabled)el.focus({preventScroll:true});}
}
function loginHTML(){return `<section class="panel"><h2>เข้าใช้${u.role==='manager'?'ผู้จัดการ':'ครัวและหน้าร้าน'} <span class="tag">PIN/สิทธิ์ จำลอง</span></h2><p>บัญชีเริ่มต้นทุกบัญชีใช้ PIN <strong>0000</strong> เป็น placeholder สาธารณะ</p><form id="login-form"><div class="fields"><label>ชื่อผู้ใช้จำลอง<select data-testid="staff-user">${choices(s.accounts,u.loginUser,'username','username')}</select></label><label>PIN จำลอง<input data-testid="staff-pin" type="password" inputmode="numeric" autocomplete="off" placeholder="0000"></label></div><button data-testid="btn-login" type="submit" class="primary">เข้าใช้</button></form><small>ผิด 5 ครั้งติดล็อกบัญชีนั้น 5 นาทีตามนาฬิกาจำลอง</small></section>`;}
function customerHTML(){
 const cart=currentCart(),open=u.mode==='takeaway'?u.takeawayOpened:!!session()&&session().state==='open',o=latest(),p=payment(o),list=ensureSlot();
 const m=s.menus.find(m=>m.id===u.selectedMenu);const selected=m?.options.filter(x=>u.selectedOptions.includes(x.id))??[];
 return `<section data-testid="screen-customer"><div class="panel"><div class="split"><h2>วันนี้รับอะไรดี</h2><span class="tag">QR โต๊ะ จำลอง</span></div><div class="fields"><label>รูปแบบการสั่ง<select data-testid="order-mode"><option value="dine-in" ${u.mode==='dine-in'?'selected':''}>ทานที่ร้าน</option><option value="takeaway" ${u.mode==='takeaway'?'selected':''}>สั่งกลับบ้าน</option></select></label><label ${u.mode==='takeaway'?'hidden':''}>เลือกโต๊ะ แทนสแกน QR ที่มี table_id<select data-testid="table-select">${choices(s.tables,u.table,'table_id','label')}</select></label><label ${u.mode!=='takeaway'?'hidden':''}>ช่วงรับอาหาร • เวลาจำลอง<select data-testid="pickup-slot">${list.map(x=>`<option value="${x.value}" ${u.slot===x.t?'selected':''}>${x.value} (${x.date})</option>`).join('')}</select></label></div>${button('btn-open-menu','เปิดเมนู / เริ่มรอบสั่ง','open-menu','class="primary"')}<div class="row" style="margin-top:12px"><strong data-testid="active-table">${open?(u.mode==='takeaway'?'สั่งกลับบ้าน':'โต๊ะ '+esc(session().table_id)):'ยังไม่เปิดรอบสั่ง'}</strong><span>Session: <span data-testid="session-id">${u.mode==='dine-in'&&open?esc(u.session):''}</span></span></div></div>
 ${open?`<div class="grid"><div><section data-testid="menu-list" class="panel"><div class="split"><h2>เมนูจากครัว</h2><small>${s.menus.length} เมนู • ราคาจำลอง</small></div><div class="menu-grid">${s.menus.map((m,i)=>`<button data-testid="menu-item-${esc(m.id)}" data-action="select-menu" data-id="${esc(m.id)}" class="food" ${menuAvailable(m)?'':'disabled'}><span class="food-art">${m.image?`<img src="${esc(m.image)}" alt="${esc(m.name)}">`:`<span aria-hidden="true">${i===7?'◉':'♨'}</span>`}</span><span class="food-text"><strong>${esc(m.name)}</strong><span>${money(m.price)} · ${menuAvailable(m)?'สั่งได้':(!m.available?'ปิดขายโดยผู้จัดการ':'หมด')}</span></span></button>`).join('')||'<p>ยังไม่มีเมนู</p>'}</div></section>
 <section class="panel" aria-label="รายละเอียดจานที่เลือก"><h2>${m?esc(m.name):'เลือกเมนูเพื่อดูตัวเลือก'}</h2>${m?`${m.options.map(x=>`<label class="check"><input type="checkbox" data-testid="option-${esc(x.id)}" data-option="${esc(x.id)}" ${u.selectedOptions.includes(x.id)?'checked':''} ${optionAvailable(m,x)?'':'disabled'}>${esc(x.name)} +${money(x.price)} ${optionAvailable(m,x)?'':'· หมด / ปิดขาย'}</label>`).join('')||'<p class="muted">ไม่มีตัวเลือกเพิ่ม</p>'}<div class="split" style="margin-top:14px"><strong data-testid="item-total" class="amount">${money((cents(m.price)+selected.reduce((n,x)=>n+cents(x.price),0))/100)}</strong>${button('btn-add-item','เพิ่มลงตะกร้า','add-item',`class="primary" ${menuAvailable(m)?'':'disabled'}`)}</div>`:''}</section></div>
 <aside><section class="panel"><div class="split"><h2>ตะกร้าของคุณ</h2><span><span data-testid="cart-count">${cart.length}</span> จาน</span></div>${cart.length?`<ul class="list">${cart.map((i,n)=>`<li>${esc(i.name)}${i.options.length?' · '+i.options.map(x=>esc(x.name)).join(', '):''}<div class="split"><span>${money(i.total)}</span>${button('','นำออก','remove-cart',`data-id="${n}" aria-label="นำ ${esc(i.name)} ออกจากตะกร้า"`)}</div></li>`).join('')}</ul>`:'<p class="empty">เลือกจานโปรดจากเมนูได้เลย</p>'}<div class="split"><strong>รวม</strong><strong class="amount" data-testid="cart-total">${money(sum(cart))}</strong></div><p class="notice">เวลารอ (US-07): ยังประมาณไม่ได้ — seed ไม่มีค่าเฉลี่ย 7 วันและต่อเมนู; DI-07/A-05 ยังไม่ยืนยัน “พร้อมเสิร์ฟ”</p>${button('btn-submit-order','ส่งออเดอร์เข้าครัว','submit-order','class="primary"')}<p class="message" role="status" data-testid="order-message">${esc(u.orderMessage)}</p></section>
 <section class="panel"><h2>ติดตามออเดอร์ล่าสุด</h2><div class="row"><span>ออเดอร์ <strong data-testid="order-id">${o?.id??''}</strong></span><strong data-testid="takeaway-id">${esc(o?.takeaway_id??'')}</strong></div><p><span class="status" data-testid="customer-order-status">${o?statuses[o.status]:''}</span></p><p class="muted">การแจ้งเตือนสถานะ จำลอง • อัปเดตในแท็บเดียว<br>ชื่อสถานะตาม fixture; DI-07/A-05 ยังไม่ยืนยันการแมป</p>${o?`<p>ยอดออเดอร์ ${money(o.total)}</p>${itemsHTML(o)}`:''}<h3>การชำระเงิน <span class="tag">จำลอง</span></h3><p data-testid="payment-status">${p?.state??'ยังไม่จ่าย'}</p><div class="row">${button('pay-cash','เลือกเงินสด','cash',!o||p?.state==='จ่ายแล้ว'?'disabled':'')}${button('pay-promptpay','PromptPay จำลอง','promptpay',!o||p?.state==='จ่ายแล้ว'?'disabled':'')}</div><p class="message" data-testid="cash-message">${esc(cashMessage(p))}</p>${p?.method==='promptpay'&&p.state!=='จ่ายแล้ว'?'<div class="qr" role="img" aria-label="ภาพแทน QR PromptPay จำลอง สแกนชำระเงินจริงไม่ได้"><span>QR จำลอง<br>ห้ามโอนเงินจริง</span></div><p>ค้างจ่ายจนหน้าร้านยืนยันสลิปจำลอง</p>':''}<small>เลือกวิธีจ่ายยังไม่เท่ากับหน้าร้านรับเงิน</small></section>
 <details class="panel"><summary>ออเดอร์ทั้งหมดในรอบนี้ (${sessionOrders().length})</summary>${sessionOrders().map(x=>`<article class="ticket">#${x.id} ${esc(x.takeaway_id||'โต๊ะ '+x.table_id)} · ${statuses[x.status]} · ${money(x.total)} · ${payment(x).state}${itemsHTML(x)}${x.id!==o?.id&&payment(x).state!=='จ่ายแล้ว'?`<div class="row">${button('','เลือกเงินสด #'+x.id,'cash',`data-id="${x.id}"`)}${button('','เลือก PromptPay จำลอง #'+x.id,'promptpay',`data-id="${x.id}"`)}</div><p>${esc(cashMessage(payment(x)))}</p>${payment(x).method==='promptpay'?'<p class="notice">QR PromptPay จำลอง — ค้างจ่าย โปรดให้หน้าร้านยืนยัน ไม่มีการโอนเงินจริง</p>':''}`:''}</article>`).join('')||'<p>ยังไม่มีออเดอร์</p>'}</details></aside></div>`:`<div class="panel empty">เปิดเมนูเพื่อเริ่มเลือกอาหาร${session()?.state==='closed'?' • รอบโต๊ะเดิมปิดแล้ว ต้องเริ่ม session ใหม่':''}</div>`}</section>`;
}
function cashMessage(p){if(p?.state==='จ่ายแล้ว')return '';if(!s.promptpay)return 'PromptPay จำลองปิดบริการ กรุณาชำระเงินสดที่หน้าร้าน';if(p?.requested_at!==null&&p?.requested_at!==undefined&&s.now-p.requested_at>=600000)return 'ยังไม่ยืนยันถึง 10 นาที กรุณาชำระเงินสดที่หน้าร้าน';if(p?.method==='cash')return 'เลือกเงินสดแล้ว กรุณาชำระที่หน้าร้านและรอพนักงานกดรับเงิน';return '';}
function itemsHTML(o){return `<ul class="list">${orderItems(o).map(i=>`<li>${esc(i.name)}${i.options.length?' · '+i.options.map(x=>esc(x.name)).join(', '):''} — ${money(i.total)}</li>`).join('')}</ul>`;}
function staffNav(){return `<div class="subnav">${can('kitchen')?button('nav-kitchen','คิวครัว','nav','data-page="kitchen"'):''}${can('front')?button('nav-front','หน้าร้าน','nav','data-page="front"'):''}${button('','ออกจากระบบจำลอง','logout')}</div>`;}
function staffHTML(){return `<section data-testid="screen-staff">${u.user?`<p>ผู้ใช้จำลอง <strong>${esc(u.user.username)}</strong> · ${esc(u.user.role)}</p>${staffNav()}${u.page==='kitchen'&&can('kitchen')?kitchenHTML():u.page==='front'&&can('front')?frontHTML():''}`:'<p class="muted">กรุณาเข้าสู่ระบบจำลองเพื่อเปิดคิวครัวหรือหน้าร้าน</p>'}</section>`;}
function kitchenHTML(){const i=s.ingredients.find(i=>i.id===u.ingredient);const queue=[...s.orders].sort((a,b)=>a.received_at.localeCompare(b.received_at)||a.id-b.id);return `<div class="grid"><section class="panel"><h2>คิวครัว</h2><p class="muted">เรียงเวลาจำลองระดับวินาที แล้วเลขออเดอร์ • กดหนึ่งครั้งเลื่อนหนึ่งขั้น</p><div data-testid="kitchen-queue">${queue.map(o=>`<article class="ticket" data-testid="kitchen-order" data-order-id="${o.id}" data-received-at="${o.received_at}"><div class="split"><h3>#${o.id} · ${o.channel==='takeaway'?'สั่งกลับบ้าน '+esc(o.takeaway_id):'โต๊ะ '+esc(o.table_id)}</h3><span class="status">${statuses[o.status]}</span></div><time>${o.received_at}</time>${o.channel==='takeaway'?`<p>รับ ${esc(o.pickup_date)} ${esc(o.pickup_slot)}</p>`:''}${itemsHTML(o)}${button('btn-status-next',o.status<2?'เปลี่ยนเป็น '+statuses[o.status+1]:'เสร็จแล้ว','next-status',`data-id="${o.id}" ${o.status===2?'disabled':''}`)}</article>`).join('')||'<p class="empty">ยังไม่มีออเดอร์ในคิว</p>'}</div></section><section class="panel"><h2>ความพร้อมวัตถุดิบ</h2><label>วัตถุดิบ<select data-testid="ingredient-select">${choices(s.ingredients,u.ingredient)}</select></label><p data-testid="ingredient-status">${esc(i?.name)} · ${i?.available?'มี':'หมด'}</p><div class="row">${button('btn-out-of-stock','วัตถุดิบหมด','stock','data-available="false" class="danger"')}${button('btn-restock','กลับมามี','stock','data-available="true"')}</div><p class="muted">ผลจำลองตามแมป whole / option • เปิดคืนเมื่อไม่มีวัตถุดิบอื่นหมดค้าง และผู้จัดการไม่ได้ปิดขาย</p><p class="notice">DI-04/A-03 ยังไม่ยืนยันการเชื่อม US-20 กับ US-12/US-13</p></section></div>`;}
function frontHTML(){return `<section class="panel"><h2>หน้าร้าน • ออเดอร์และการรับเงิน</h2><p>ยอดแต่ละออเดอร์คงตามข้อมูลขณะส่ง • สลิปและการรับเงิน <span class="tag">จำลอง</span></p><div data-testid="front-orders">${s.orders.map(o=>{const p=payment(o),old=o.session_id&&s.sessions.find(x=>x.id===o.session_id)?.state==='closed';return `<article data-testid="front-order" data-order-id="${o.id}" data-table-id="${esc(o.table_id)}" class="ticket"><div class="split"><h3>#${o.id} · ${o.channel==='takeaway'?'สั่งกลับบ้าน '+esc(o.takeaway_id):'โต๊ะ '+esc(o.table_id)}</h3><span class="status">${statuses[o.status]}</span></div><small>${o.received_at} · ${esc(o.session_id||o.pickup_date+' '+o.pickup_slot)} ${old?'· ประวัติรอบที่ปิดแล้ว':''}</small>${itemsHTML(o)}<div class="split"><strong data-testid="front-total" class="amount">${money(o.total)}</strong><strong data-testid="front-payment-status">${p.state}</strong></div><p>วิธีที่เลือก: ${p.method==='cash'?'เงินสด':p.method==='promptpay'?'PromptPay จำลอง':'ยังไม่เลือก'}</p><div class="row">${button('btn-confirm-slip','ยืนยันสลิปจำลอง','confirm-slip',`data-id="${o.id}" ${p.state==='จ่ายแล้ว'||p.requested_at===null?'disabled':''}`)}${button('btn-receive-cash','รับเงินสดจำลอง','receive-cash',`data-id="${o.id}" ${p.state==='จ่ายแล้ว'?'disabled':''}`)}</div></article>`;}).join('')||'<p class="empty">ยังไม่มีออเดอร์</p>'}</div></section><section class="panel"><h2>รอบโต๊ะ</h2><label>เลือกโต๊ะ<select data-testid="front-table-select">${choices(s.tables,u.frontTable,'table_id','label')}</select></label><p>${s.sessions.filter(x=>x.table_id===u.frontTable&&x.state==='open').map(x=>esc(x.id)+' · เปิดรอบ').join('')||'ไม่มีรอบที่เปิดอยู่'}</p><div class="row">${button('','เปิดรอบโต๊ะจำลอง','front-open')}${button('btn-close-table','ปิดรอบโต๊ะที่เลือก','close-table','class="danger"')}</div><p class="muted">ปิดแล้วสั่งต่อรอบเดิมไม่ได้ เก็บออเดอร์เก่าในประวัติ • mock ไม่บังคับจ่ายครบก่อนปิด เพราะ Q-16 ยังไม่ยืนยัน</p><p class="message" role="status">${esc(u.frontMessage)}</p></section><section class="panel"><h2>บันทึกเหตุการณ์ชำระเงิน <span class="tag">จำลอง</span></h2><div data-testid="payment-log">${s.paymentEvents.map(e=>`<p>#${e.order_id} · ${esc(e.actor)} · ${e.at} · ${esc(e.action)}</p>`).join('')||'ยังไม่มีเหตุการณ์'}</div></section>`;}
function managerHTML(){return `<section data-testid="screen-manager"><p>ผู้จัดการจำลอง <strong>${esc(u.user.username)}</strong></p><div class="panel"><label class="check"><input data-testid="toggle-promptpay" type="checkbox" ${s.promptpay?'checked':''}>เปิดบริการ PromptPay จำลอง</label><small>ไม่ตั้งบัญชีธนาคารจริง ไม่มีการสร้าง QR สำหรับโอนเงินจริง</small></div><nav class="subnav" aria-label="งานผู้จัดการ">${button('nav-menu-admin','จัดการเมนู','nav','data-page="menu"')}${button('nav-mapping','แมปวัตถุดิบ','nav','data-page="mapping"')}${button('nav-accounts','บัญชีและ PIN','nav','data-page="accounts"')}${button('','รายงาน (ตรวจสิทธิ์)','nav','data-page="reports"')}</nav>${staffNav()}${u.page==='menu'?adminHTML():u.page==='mapping'?mappingHTML():u.page==='accounts'?accountsHTML():u.page==='reports'?'<section data-testid="report-screen" class="panel"><h2>รายงาน • Placeholder</h2><p>หน้านี้ใช้ตรวจสิทธิ์ US-25 เท่านั้น ไม่สร้างรายงาน US-23 นอกขอบเขต</p></section>':u.page==='kitchen'?kitchenHTML():u.page==='front'?frontHTML():'<div class="panel">เลือกงานจากเมนูด้านบน</div>'}</section>`;}
function loadDraft(id){u.adminId=id;const m=s.menus.find(m=>m.id===id);u.draft=m?clone(m):{name:'',price:0,image:null,available:true,options:[]};u.draft.pendingName='';u.draft.pendingPrice='0';u.draft.imageError='';u.draft.imageLoading=false;}
function adminHTML(){if(!u.draft)loadDraft(u.adminId);const d=u.draft;return `<section data-testid="menu-admin" class="panel"><h2>จัดการเมนู</h2><p class="muted">เพิ่ม/แก้เมนูและตัวเลือก 0–10 รายการ • เมนูที่ส่งแล้วเก็บชื่อและราคาเดิม</p><label>เลือกเมนู<select data-testid="admin-menu-select"><option value="new" ${u.adminId==='new'?'selected':''}>+ สร้างเมนูใหม่</option>${choices(s.menus,u.adminId)}</select></label><div class="fields"><label>ชื่อเมนู<input data-testid="admin-menu-name" value="${esc(d.name)}"></label><label>ราคา (บาท ≥ 0)<input data-testid="admin-menu-price" type="number" min="0" step="0.01" value="${esc(d.price)}"></label><label>รูป jpg/png ≤ 2 MB<input data-testid="admin-menu-image" type="file" accept=".jpg,.jpeg,.png,image/jpeg,image/png"></label></div><label class="check"><input id="admin-available" type="checkbox" ${d.available?'checked':''}>เปิดขายโดยผู้จัดการ (แยกจากวัตถุดิบ)</label>${d.image?`<div class="row"><img alt="รูปเมนูที่เลือก" src="${esc(d.image)}" width="100" height="80" style="object-fit:cover">${button('','นำรูปออก','remove-image')}</div>`:''}<p class="message" role="status">${esc(d.imageError|| (d.imageLoading?'กำลังอ่านรูปในเครื่อง…':''))}</p><h3>ตัวเลือกเพิ่ม (${d.options.length}/10)</h3>${d.options.map((x,i)=>`<div class="option-row"><label>ชื่อตัวเลือก ${i+1}<input data-draft-option="${i}" data-field="name" value="${esc(x.name)}"></label><label>ราคาเพิ่ม<input type="number" min="0" step="0.01" data-draft-option="${i}" data-field="price" value="${esc(x.price)}"></label>${button('','ลบตัวเลือก','remove-option',`data-id="${i}"`)}</div>`).join('')}<div class="fields"><label>ชื่อตัวเลือกใหม่<input data-testid="admin-option-name" value="${esc(d.pendingName)}"></label><label>ราคาเพิ่ม (บาท ≥ 0)<input data-testid="admin-option-price" type="number" min="0" step="0.01" value="${esc(d.pendingPrice)}"></label></div>${button('','เพิ่มตัวเลือกในแบบร่าง','add-option')}<p class="muted">ปุ่มบันทึกเมนูจะรวมตัวเลือกใหม่ที่กรอกค้างไว้ด้วย</p><div class="row">${button('btn-save-menu','บันทึกเมนู','save-menu','class="primary"')}${button('btn-delete-menu','ลบเมนู','delete-menu',`class="danger" ${u.adminId==='new'?'disabled':''}`)}</div><p data-testid="admin-message" class="message" role="status">${esc(u.adminMessage)}</p></section>`;}
function mappingHTML(){if(!s.menus.some(m=>m.id===u.mappingMenu))u.mappingMenu=s.menus[0]?.id??'';const m=s.menus.find(m=>m.id===u.mappingMenu);if(!m?.options.some(x=>x.id===u.mappingOption))u.mappingOption=m?.options[0]?.id??'';return `<section class="panel"><h2>แมปวัตถุดิบ</h2><p>เลือกได้เฉพาะเมนูและตัวเลือกที่บันทึกแล้วในหน้าจัดการเมนู</p><p class="notice">US-20 ต้นฉบับ: “กฎปิด/เปิดเมนูอัตโนมัติ (US-14)” • DI-04/A-03 ยังไม่ยืนยันการเชื่อม US-12/US-13 • A-02: หมายเหตุ ค. ไม่มีนิยาม</p><div class="fields"><label>เมนู<select data-testid="mapping-menu">${choices(s.menus,u.mappingMenu)}</select></label><label>ขอบเขต<select data-testid="mapping-scope"><option value="whole" ${u.mappingScope==='whole'?'selected':''}>ทั้งจาน (whole)</option><option value="option" ${u.mappingScope==='option'?'selected':''}>เฉพาะตัวเลือก (option)</option></select></label><label>ตัวเลือกของเมนู<select data-testid="mapping-option" ${u.mappingScope==='whole'?'disabled':''}>${choices(m?.options??[],u.mappingOption)}</select></label><label>วัตถุดิบ<select data-testid="mapping-ingredient">${choices(s.ingredients,u.mappingIngredient)}</select></label></div>${button('btn-save-mapping','เพิ่มความสัมพันธ์','save-mapping','class="primary"')}<p class="message" role="status">${esc(u.mappingMessage)}</p><div data-testid="mapping-list">${s.mappings.map(m=>`<p><code>${esc(m.menu_id)} → ${esc(m.ingredient_id)} · ${esc(m.scope)} · ${esc(m.option_id??'—')}</code></p>`).join('')||'ยังไม่มีแมป'}</div></section>`;}
function accountsHTML(){return `<section class="panel"><h2>บัญชีและสิทธิ์ <span class="tag">จำลอง</span></h2><p>ชื่อผู้ใช้ตัวอักษร/ตัวเลข 3–20 ตัว • PIN ตัวเลข 4–6 หลัก • ไม่ใช้บัญชีจริง</p><div class="fields"><label>ชื่อผู้ใช้ใหม่<input data-testid="account-username" autocomplete="off"></label><label>PIN ใหม่ จำลอง<input data-testid="account-pin" type="password" inputmode="numeric" autocomplete="off"></label><label>บทบาท<select data-testid="account-role"><option value="kitchen">ครัว</option><option value="front">หน้าร้าน</option><option value="manager">ผู้จัดการ</option></select></label></div>${button('btn-save-account','สร้างบัญชีจำลอง','save-account','class="primary"')}<p data-testid="account-message" role="status" class="message">${esc(u.accountMessage)}</p><ul>${s.accounts.map(a=>`<li>${esc(a.username)} · ${esc(a.role)} ${a.lockedUntil>s.now?'· ล็อกถึง '+iso(a.lockedUntil):''}</li>`).join('')}</ul></section>`;}
function login(){const a=s.accounts.find(a=>a.username===val('staff-user')),pin=val('staff-pin');u.loginUser=val('staff-user');u.user=null;if(!a){u.auth='ปฏิเสธ: ไม่พบบัญชีจำลอง';return render();}if(a.lockedUntil>s.now){u.auth='ปฏิเสธ: บัญชีถูกล็อก 5 นาที ถึง '+iso(a.lockedUntil);return render();}if(a.lockedUntil){a.failures=0;a.lockedUntil=0;}if(a.pin!==pin){a.failures++;if(a.failures>=5){a.lockedUntil=s.now+300000;u.auth='ปฏิเสธ: PIN ผิด 5 ครั้ง บัญชีถูกล็อก 5 นาที ถึง '+iso(a.lockedUntil);}else u.auth=`ปฏิเสธ: PIN ไม่ถูกต้อง (${a.failures}/5)`;return render();}a.failures=0;if(u.role==='manager'&&a.role!=='manager'){u.auth='ปฏิเสธ: ต้องใช้บัญชีผู้จัดการจำลอง';return render();}u.user={username:a.username,role:a.role};u.auth='เข้าใช้สำเร็จ: '+a.username+' · PIN/สิทธิ์จำลอง';if(u.role==='manager'){navigate('menu');}else{u.page=a.role==='front'?'front':'kitchen';render();}}
function navigate(page){if(['menu','mapping','accounts','reports'].includes(page)){if(!can('manager'))return deny();u.role='manager';u.page=page;history.pushState(null,'','#/manager/'+page);}else{if(!can(page))return deny();u.page=page;history.replaceState(null,'','#/'+(u.role==='manager'?'manager':'staff')+'/'+page);}render();}
function handleRoute(){const route=location.hash.slice(1);if(route.startsWith('/manager/')){if(!can('manager')){u.auth='ปฏิเสธ: ไม่มีสิทธิ์เข้าหน้าผู้จัดการผ่าน URL (จำลอง)';if(u.role!=='customer')u.page='';return render();}const page=route.split('/')[2];u.role='manager';u.page=['menu','mapping','accounts','reports','kitchen','front'].includes(page)?page:'';render();}else if(route.startsWith('/staff/')){const page=route.split('/')[2];if(!['kitchen','front'].includes(page)||!can(page)){u.page='';return deny();}u.page=page;render();}}
function selectRole(role){epoch++;u.user=null;u.role=role;u.page='';u.auth='';u.draft=null;u.adminMessage='';u.loginUser=role==='manager'?'demomanager':'demokitchen';history.replaceState(null,'',location.pathname+location.search);render();}
function addItem(){const m=s.menus.find(x=>x.id===u.selectedMenu);if(!menuAvailable(m)||m.options.some(o=>u.selectedOptions.includes(o.id)&&!optionAvailable(m,o))){u.orderMessage='ปฏิเสธ: เมนูหรือตัวเลือกหมด / ปิดขาย';return render();}const options=m.options.filter(x=>u.selectedOptions.includes(x.id)).map(clone);const item={menu_id:m.id,name:m.name,price:m.price,options,total:(cents(m.price)+options.reduce((n,x)=>n+cents(x.price),0))/100};currentCart().push(item);u.orderMessage='เพิ่มลงตะกร้าแล้ว';render();}
function submitOrder(){const cart=currentCart();if(u.mode==='dine-in'&&session()?.state!=='open'){u.orderMessage='ปฏิเสธ: session โต๊ะปิดแล้ว กรุณาเปิดเมนูใหม่';return render();}if(!cart.length){u.orderMessage='กรุณาเพิ่มอาหารลงตะกร้า';return render();}
 // Validate the entire basket before issuing any order, item, payment or queue entry.
 const invalid=cart.find(i=>{const m=s.menus.find(m=>m.id===i.menu_id);return !menuAvailable(m)||i.options.some(o=>!m.options.some(x=>x.id===o.id)||!optionAvailable(m,o));});
 if(invalid){u.orderMessage='ปฏิเสธ: '+invalid.name+' หรือวัตถุดิบ/ตัวเลือกหมด ถูกปิดขาย หรือถูกลบ กรุณานำรายการออกแล้วเลือกใหม่';return render();}
 // Mock policy: refresh a stale catalog price for review, requiring another submit.
 let changed=false;for(const i of cart){const m=s.menus.find(m=>m.id===i.menu_id),options=i.options.map(o=>clone(m.options.find(x=>x.id===o.id)));const total=(cents(m.price)+options.reduce((n,x)=>n+cents(x.price),0))/100;if(i.price!==m.price||i.name!==m.name||JSON.stringify(i.options)!==JSON.stringify(options)){Object.assign(i,{name:m.name,price:m.price,options,total});changed=true;}}
 if(changed){u.orderMessage='ราคา/รายละเอียดเปลี่ยนแล้ว กรุณาตรวจตะกร้าและกดส่งอีกครั้ง (นโยบายจำลอง)';return render();}
 const slot=u.mode==='takeaway'?slots().find(x=>x.t===u.slot):null;if(u.mode==='takeaway'&&!slot){u.orderMessage='ช่วงรับเดิมผ่านเวลาแล้ว กรุณาเลือกช่วงรับใหม่อย่างน้อย 20 นาที';ensureSlot();return render();}
 let takeaway_id=null;if(u.mode==='takeaway'){if(s.takeawayDay!==day()){s.takeawayDay=day();s.takeawaySequence=0;}takeaway_id='T-'+String(++s.takeawaySequence).padStart(3,'0');}
 const o={id:s.nextOrder++,channel:u.mode,table_id:u.mode==='dine-in'?session().table_id:'takeaway',session_id:u.mode==='dine-in'?u.session:null,received_at:iso(Math.floor(s.now/1000)*1000),confirmed_at:iso(),status:0,total:sum(cart),takeaway_id,pickup_slot:slot?.value??null,pickup_date:slot?.date??null};
 s.orders.push(o);for(const i of cart)s.items.push({...clone(i),id:s.nextItem++,order_id:o.id});s.payments.push({order_id:o.id,total:o.total,state:'ยังไม่จ่าย',method:null,requested_at:null});s.paymentEvents.push({order_id:o.id,actor:'ลูกค้าจำลอง',at:iso(),action:'ออเดอร์ใหม่ · ยังไม่จ่าย'});cart.splice(0);u.orderMessage='ส่งออเดอร์ #'+o.id+' แล้ว • แจ้งครัวจำลอง';render();
}
function choosePayment(method,id){const o=id?s.orders.find(o=>o.id===Number(id)):latest();if(!o||!sessionOrders().includes(o))return;const p=payment(o);if(p.state==='จ่ายแล้ว')return;if(method==='promptpay'&&!s.promptpay)return render();p.method=method;if(method==='promptpay'){p.state='ค้างจ่าย';if(p.requested_at===null)p.requested_at=s.now;}else p.state='ยังไม่จ่าย';s.paymentEvents.push({order_id:o.id,actor:'ลูกค้าจำลอง',at:iso(),action:'เลือก '+(method==='cash'?'เงินสด (ยังไม่รับเงิน)':'PromptPay จำลอง · ค้างจ่าย')});render();}
function confirmPayment(id,method){if(!can('front'))return deny();const p=s.payments.find(p=>p.order_id===Number(id));if(!p||p.state==='จ่ายแล้ว'||(method==='slip'&&p.requested_at===null))return;p.state='จ่ายแล้ว';p.method=method==='slip'?'promptpay':'cash';s.paymentEvents.push({order_id:p.order_id,actor:u.user.username,at:iso(),action:method==='slip'?'ยืนยันสลิปจำลอง · จ่ายแล้ว':'รับเงินสดจำลอง · จ่ายแล้ว'});render();}
function validPrice(v){return String(v).trim()!==''&&Number.isFinite(Number(v))&&Number(v)>=0&&Number(v)<=Number.MAX_SAFE_INTEGER/100&&Number.isSafeInteger(Math.round(Number(v)*100));}
function addOption(){const d=u.draft;if(!d.pendingName.trim()||!validPrice(d.pendingPrice)){u.adminMessage='ปฏิเสธ: กรุณาระบุชื่อตัวเลือกและราคาเพิ่ม ≥ 0';return false;}if(d.options.length>=10){u.adminMessage='ปฏิเสธ: ตัวเลือกได้ไม่เกิน 10 รายการ';return false;}d.options.push({id:'opt-'+s.nextOption++,name:d.pendingName.trim(),price:cents(d.pendingPrice)/100});d.pendingName='';d.pendingPrice='0';return true;}
function saveMenu(){if(!can('manager'))return deny();const d=u.draft;if(d.imageLoading||d.imageError){u.adminMessage='ปฏิเสธ: รอรูปอ่านเสร็จหรือเลือกรูปใหม่ที่ถูกต้อง';return render();}if(!d.name.trim()||!validPrice(d.price)||d.options.some(o=>!o.name.trim()||!validPrice(o.price))){u.adminMessage='ปฏิเสธ: ชื่อห้ามว่าง ราคาเมนูและตัวเลือกต้อง ≥ 0';return render();}if(d.pendingName.trim()&&!addOption())return render();if(d.options.length>10){u.adminMessage='ปฏิเสธ: ตัวเลือกได้ 0–10 รายการ';return render();}
 const id=u.adminId==='new'?'m'+String(s.nextMenu).padStart(2,'0'):u.adminId;const removed=s.mappings.filter(m=>m.menu_id===id&&m.scope==='option'&&!d.options.some(o=>o.id===m.option_id));if(removed.length&&!confirm('ตัวเลือกที่นำออกมีแมปวัตถุดิบ บันทึกแล้วจะลบแมปของตัวเลือกเหล่านี้ ยืนยันหรือไม่?')){u.adminMessage='ยกเลิกบันทึก';return render();}
 const m={id,name:d.name.trim(),price:cents(d.price)/100,image:d.image,available:d.available,options:d.options.map(o=>({id:o.id,name:o.name.trim(),price:cents(o.price)/100}))};if(u.adminId==='new'){s.nextMenu++;s.menus.push(m);}else{s.menus[s.menus.findIndex(x=>x.id===id)]=m;}s.mappings=s.mappings.filter(x=>!removed.includes(x));u.adminMessage='บันทึก '+m.name+' ('+id+') แล้ว ยอดออเดอร์เดิมคงเดิม';loadDraft(id);render();}
