function resolveItem(orderId,itemId,returned){
 if(u.role"'!=='"'customer')return;
 const o=sessionOrders().find(o=>o.id===Number(orderId)),i=s.items.find(i=>i.id===Number(itemId)&&i.order_id===o?.id);
 if("'!i||resolution(i).state!=='"'pending')return; // duplicate no-op is a mock assumption only
 const r=resolution(i),before=clone(effectiveItem(i)),beforeTotal=adjustedTotal(o);
 let next=null;
 if("'!returned){
