 if("'!menuAvailable(m)||d.options.some(id=>!m.options.some(x=>x.id===id)||!optionAvailable(m,m.options.find(x=>x.id===id)))){
 u.resolutionMessage='"'ปฏิเสธ: เมนูหรือตัวเลือกหมด / ปิดขาย / ถูกลบ ยังรอลูกค้าตัดสินใจ';return render();
 }
 const options=m.options.filter(x=>d.options.includes(x.id)).map(clone);
 next={menu_id:m.id,name:m.name,price:m.price,options,total:(cents(m.price)+options.reduce((n,x)=>n+cents(x.price),0))/100};
 }
 s.itemResolutions[i.id]={...r,state:returned?'returned':'replaced',current:next??r.current,revision:r.revision+1,resolved_at:iso()};
 const afterTotal=adjustedTotal(o);
 s.adjustments.push({order_id:o.id,item_id:i.id,revision:r.revision+1,kind:returned?'return':'replace',before_item:before,after_item:clone(next),before_total:beforeTotal,after_total:afterTotal,actor:'ลูกค้าจำลอง',at:iso()});
 s.itemEvents.push({order_id:o.id,item_id:i.id,action:returned?'คืนรายการ':'เปลี่ยนเมนู',actor:'ลูกค้าจำลอง',at:iso()});
 delete u.replacementDrafts[i.id];u.resolutionMessage=returned?'คืนรายการแล้ว ลดเฉพาะยอดจำลองและนำออกจากคิวที่ต้องทำ ไม่ใช่การโอนเงินคืน':'เปลี่ยนเมนูแล้ว จอครัวใช้รายการแทนตามที่เลือก ยอดส่วนต่างเป็นการจำลอง';
 render();
}
function capacityWindow(){
 const now=iso(),hh=Number(now.slice(11,13)),mm=Number(now.slice(14,16)),minutes=hh*60+mm;
 const toMinutes=v=>Number(v.slice(0,2))*60+Number(v.slice(3,5));
 const startText=now.slice(0,14)+String(Math.floor(mm/15)*15).padStart(2,'0')+':00+07:00';
 const start=Date.parse(startText),end=start+15*60000;
 return {start,end,active:minutes>=toMinutes(s.capacity.start)&&minutes<toMinutes(s.capacity.end),
 count:s.orders.filter(o=>{const t=Date.parse(o.confirmed_at);return t>=start&&t<end;}).length};
}
